from taf.selenium.mobile.gnb.oam.coam.classical.provider import Provider


class CoamFactory(object):

    @staticmethod
    def create(driver, download_checker, screenshot_dir, version=None):
        coam_cls = Provider.provide(version)
        coam = coam_cls(driver, download_checker, screenshot_dir)
        return coam
